package com.snowread.app;

import java.util.*;

public final class FeatureCoreTest {
    static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("FeatureCore check "+checks);}
    public static void main(String[] args)throws Exception{
        check(TitleCleaner.clean("[完结]《雪》(1-1000章)作者：某人.txt").equals("雪"));check(TitleCleaner.clean("庆余年（修订版）.TXT").equals("庆余年（修订版）"));check(TitleCleaner.clean("【某小说网】 三  体 [精校].txt").equals("三 体"));check(!TitleCleaner.clean("[完结].txt").isEmpty());check(TitleCleaner.stem("书.txt.txt").equals("书.txt"));
        String simplified="第一章 春天的故事\n他看着窗外的雨，心里想起了那个人。她说：这是我们的家，没有人会忘记这里的春天。\n";String traditional="第一章 春天的故事\n他看著窗外的雨，心裡想起了那個人。她說：這是我們的家，沒有人會忘記這裡的春天。\n";
        check(TextDocument.decode(simplified.getBytes("GB18030"),null).text.equals(simplified));TextDocument big=TextDocument.decode(traditional.getBytes("Big5"),null);check(big.encoding.equals("Big5"));check(big.text.equals(traditional));check(TextDocument.decode(traditional.getBytes("Big5"),"Big5").encodingConfidence.equals("手动指定"));
        String old="第一卷 冬\n第一章 雪\n窗外的雪花落在书页旁。😀这个位置需要在改动前后保持。\n第二章 梅\n花开在雪中，故事继续。";TextDocument a=new TextDocument(old,"UTF-8"),b=new TextDocument("版权说明\n\n"+old.replace("第一章 雪","第一章   雪"),"UTF-8");int offset=old.indexOf("这个位置"),mark=old.indexOf("花开");ReadingAnchor.Resolver anchors=new ReadingAnchor.Resolver(a),next=new ReadingAnchor.Resolver(b);ReadingAnchor saved=anchors.capture(offset);check(next.resolve(saved)==b.text.indexOf("这个位置"));check(next.resolve(anchors.capture(mark))==b.text.indexOf("花开"));int emoji=old.indexOf("😀");check(anchors.capture(emoji+1).offset==emoji);
        LinkedHashMap<Integer,String> notes=new LinkedHashMap<>();notes.put(mark,"保留这条备注");PositionMigration migration=new PositionMigration(a,b,offset,saved,Arrays.asList(mark),notes,Collections.emptyMap(),Collections.emptyList());check(!migration.approximate&&migration.offset==b.text.indexOf("这个位置"));check(migration.marks.size()==1&&migration.notes.get(b.text.indexOf("花开")).equals("保留这条备注"));
        TextDocument unrelated=new TextDocument("Chapter 1 Other\nA different novel with completely different contents.","UTF-8");PositionMigration missing=new PositionMigration(a,unrelated,offset,saved,Arrays.asList(mark),notes,Collections.emptyMap(),Collections.emptyList());check(missing.approximate&&missing.marks.isEmpty()&&missing.unresolved.size()==1);check(missing.unresolved.get(0).note.equals("保留这条备注"));PositionMigration restored=new PositionMigration(unrelated,a,missing.offset,null,missing.marks,missing.notes,missing.anchors,missing.unresolved);check(restored.marks.contains(mark)&&restored.unresolved.isEmpty());
        TextDocument duplicate=new TextDocument("第一卷 前\n第一章 相同\n前一卷。\n第二卷 后\n第一章 相同\n后一卷的内容在这里。","UTF-8");ReadingAnchor.Resolver duplicates=new ReadingAnchor.Resolver(duplicate);int latter=duplicate.text.indexOf("后一卷");check(duplicates.resolve(duplicates.capture(latter))==latter);
        String text="第一章 English\nSnow snow SNOW 😀\n第二章 More\nsNoW Snowman";TextDocument doc=new TextDocument(text,"UTF-8");SearchResults results=SearchResults.find(text,"snow",0,text.length(),true,()->false);check(results.total==5);for(SearchResults.Hit hit:results.hits)check(text.regionMatches(true,hit.offset,"snow",0,4));int end=doc.sectionEnd(0);check(SearchResults.find(text,"snow",0,end,true,()->false).total==3);check(SearchResults.find(text,"snow",0,text.length(),false,()->false).total==1);check(SearchResults.find(text,".*",0,text.length(),true,()->false).total==0);check(SearchResults.find(text,"snow",0,text.length(),true,()->true)==null);
        SearchGroups groups=new SearchGroups();groups.rebuild(doc,results);check(groups.rows.size()==7&&groups.rows.get(0).hit==-1&&groups.rows.get(0).count==3);groups.folded.add(0);groups.rebuild(doc,results);check(groups.rows.size()==4&&groups.rows.get(1).chapter==1);
        System.out.println("FeatureCoreTest: "+checks+" checks passed; title/Big5 ranking, anchors/unmapped recovery, Unicode, scoped case-insensitive search and groups");
    }
}
